import Foundation

struct ShippingRate {
  let zone: String
  let carrier: String
  let costCents: Int
}

enum ShippingZone: String, CaseIterable {
  case domestic
  case continental
  case international
}

struct ShippingRateTable {
  private let rates: [ShippingRate]

  init(rates: [ShippingRate]) {
    self.rates = rates
  }

  static let standard = ShippingRateTable(rates: [
    ShippingRate(zone: "domestic", carrier: "usps", costCents: 495),
    ShippingRate(zone: "domestic", carrier: "ups", costCents: 650),
    ShippingRate(zone: "domestic", carrier: "fedex", costCents: 720),
    ShippingRate(zone: "continental", carrier: "usps", costCents: 1495),
    ShippingRate(zone: "continental", carrier: "ups", costCents: 1850),
    ShippingRate(zone: "continental", carrier: "fedex", costCents: 1990),
    ShippingRate(zone: "international", carrier: "usps", costCents: 2995),
    ShippingRate(zone: "international", carrier: "dhl", costCents: 3450),
  ])

  func rate(zone: String, carrier: String) -> ShippingRate? {
    rates.first { $0.zone == zone && $0.carrier == carrier }
  }

  func cheapest(zone: String) -> ShippingRate? {
    rates.filter { $0.zone == zone }.min { $0.costCents < $1.costCents }
  }

  func carriers(for zone: String) -> [String] {
    rates.filter { $0.zone == zone }.map(\.carrier)
  }
}

extension ShippingRateTable {
  func estimatedDeliveryDays(zone: String, carrier: String) -> ClosedRange<Int> {
    switch (zone, carrier) {
    case ("domestic", "usps"):
      return 3...5
    case ("domestic", "ups"):
      return 2...4
    case ("domestic", "fedex"):
      return 1...3
    case ("continental", _):
      return 5...9
    case ("international", _):
      return 7...21
    default:
      return 3...10
    }
  }
}

struct ShippingQuote {
  let rate: ShippingRate
  let estimatedDays: ClosedRange<Int>
}

func quote(for zone: String, carrier: String, table: ShippingRateTable = .standard) -> ShippingQuote? {
  guard let rate = table.rate(zone: zone, carrier: carrier) else {
    return nil
  }
  let days = table.estimatedDeliveryDays(zone: zone, carrier: carrier)
  return ShippingQuote(rate: rate, estimatedDays: days)
}
